const listStockForecasts = `-- name: ListStockForecasts :many
SELECT sf.id, sf.uuid, sf.organization_id, sf.brand_id, sf.product_id, sf.computed_on, sf.is_latest, sf.on_hand_qty, sf.on_hand_meters, sf.avg_daily_30, sf.avg_daily_90, sf.seasonality_factor, sf.avg_meters_per_vehicle, sf.vehicles_left, sf.days_left, sf.depletion_date, sf.data_days, sf.status, sf.suggested_qty, sf.suggested_meters, sf.created_at, sf.updated_at, p.uuid AS product_uuid, p.sku, p.name AS product_name,
       p.unit_type, c.uuid AS category_uuid, c.name AS category_name
FROM stock_forecasts sf
JOIN products p ON p.id = sf.product_id
JOIN product_categories c ON c.id = p.category_id
WHERE sf.organization_id = $1
  AND sf.brand_id = $2
  AND sf.is_latest
  AND (
    COALESCE(cardinality($3::text[]), 0) = 0
    OR sf.status = ANY ($3::text[])
  )
  AND (
    COALESCE(cardinality($4::bigint[]), 0) = 0
    OR p.category_id = ANY ($4::bigint[])
  )
  AND ($5::numeric IS NULL OR sf.days_left >= $5::numeric)
  AND ($6::numeric IS NULL OR sf.days_left <= $6::numeric)
  AND (
    $7::text IS NULL
    OR p.name ILIKE '%' || $7::text || '%'
    OR p.sku ILIKE '%' || $7::text || '%'
  )
ORDER BY
  CASE WHEN NOT $8::bool AND $9::text = 'days_left' THEN sf.days_left END ASC NULLS LAST,
  CASE WHEN $8::bool AND $9::text = 'days_left' THEN sf.days_left END DESC NULLS LAST,
  CASE WHEN NOT $8::bool AND $9::text = 'depletion_date' THEN sf.depletion_date END ASC NULLS LAST,
  CASE WHEN $8::bool AND $9::text = 'depletion_date' THEN sf.depletion_date END DESC NULLS LAST,
  CASE WHEN NOT $8::bool THEN
    CASE $9::text WHEN 'product_name' THEN p.name WHEN 'status' THEN sf.status END
  END ASC,
  CASE WHEN $8::bool THEN
    CASE $9::text WHEN 'product_name' THEN p.name WHEN 'status' THEN sf.status END
  END DESC,
  CASE WHEN NOT $8::bool AND $9::text = 'avg_daily_30' THEN sf.avg_daily_30 END ASC,
  CASE WHEN $8::bool AND $9::text = 'avg_daily_30' THEN sf.avg_daily_30 END DESC,
  CASE WHEN $8::bool THEN sf.product_id END DESC,
  sf.product_id ASC
LIMIT $11 OFFSET $10
`

